// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address owner_, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(owner_);
        c.initialize(1, 1, "v", address(this));

        vm.prank(caller);
        uint256 snapshot = vm.snapshot();
        address reported = c.owner();
        vm.revertTo(snapshot);

        assertTrue(reported == owner_);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Factory f;

    function setUp() public {
        f = new Factory();
        c = new C();
        vm.prank(address(f));
        c.initialize(1, 1, "v", address(f));
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(f));
        vm.assume(caller != address(c));
        // The owner must be a fixed, caller-independent address: any two callers
        // (here: the fuzzed caller and the initializing owner) must observe the same owner.
        vm.prank(caller);
        address seenByCaller = c.owner();
        vm.prank(address(f));
        address seenByOwner = c.owner();
        assertTrue(seenByCaller == seenByOwner);
    }
}

contract Factory {
    function protocolFeeDestination() external pure returns (address) {
        return address(0xdead);
    }
}
